            </li>
          </ul>
        </div>
      </div>
    </div>

    <!-- RIGHT -->
    <div class="col-md-3 mb-3">
      <div class="card shadow-sm">
        <div class="card-header bg-dark text-white">Item Details</div>
        <div class="card-body">

