            <hr>

            <div class="row">


<!-- Store IDs -->
<div class="col-md-6">
  <div class="card h-100 text-center" style="cursor:pointer;" @click="getStoreDetails(selectedItem.store_ids)">
    <div class="card-body">
      <h6>STORES</h6>
      <div v-if="storeDetailsLoading" v-html="itemShimmer()"></div>
      <p v-else class="fs-3 fw-bold text-primary mb-0">{{ selectedItem.store_ids?.length ?? 0 }}</p>
    </div>
  </div>
</div>

<!-- LPO / Orders -->
<div class="col-md-6">
  <div class="card h-100 text-center" style="cursor:pointer;" @click="getOrderDetails(selectedItem.lpo_ids)">
    <div class="card-body">
      <h6>ORDERS</h6>
      <div v-if="orderDetailsLoading" v-html="itemShimmer()"></div>
      <p v-else class="fs-3 fw-bold text-success mb-0">{{ selectedItem.lpo_ids?.length ?? 0 }}</p>
    </div>
  </div>
</div>

<!-- GRN IDs -->
<div class="col-md-6 mt-3">
  <div class="card h-100 text-center" style="cursor:pointer;" @click="getGrnDetails(selectedItem.lpo_ids)">
