                        <v-client-table :data="orderDetails" :columns="orderColumns" :options="table_option">
                          
                        <template #order="props">
                           <router-link :to="`/approval-chain/${props.row.order}`" class="badge bg-primary">{{ props.row.order }}</router-link>      
                        </template>
                        </v-client-table>
                    </div>
        </div>
      </div>
  </div>

<div v-if="activeSection === 'grn'">
    <div  class="card shadow-sm ">
