<script setup>
import { ref, onMounted, watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect'
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css'

const itemShimmer = inject('itemShimmer')
const tableShimmer = inject('tableShimmer')
const formatDate = inject('formatDate')
const formatNumber = inject('formatNumber')
const waitIndicator = inject('waitIndicator')
 
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})

const items = ref([])
const selectedItem = ref(null)
const loading = ref(false)
const activeSection = ref('') 

const storeDetailsLoading = ref(false)

const getItems = async (param) => {
  loading.value = true
  selectedItem.value = ''
  activeSection.value = ''
  items.value = []
  storeDetails.value = []
  const res = await axiosInstance.get(`/item-reports?${param}`)
  items.value = res.data
  loading.value = false
}

const itemsList = ref([])
const item = ref('')
const filter_by = ref('category')
const item_id = ref('')

const changeFilter = (filter) => {
  filter_by.value = filter
}

const isloading = ref(false)
const getItemsList = async () => {
  isloading.value = true
  const response = await axiosInstance.get('/item-list')
  itemsList.value = response.data
  isloading.value = false
}

const selectItem = (row) => {
  selectedItem.value = row
  storeDetails.value = [] 
  activeSection.value = ''
}

const storeDetails = ref([])
const storeColumns = ref(['SNo','project','name','location','quantity']); 
const getStoreDetails = async (storeIds) => {
  if (!storeIds || storeIds.length === 0) return
  storeDetailsLoading.value = true
  activeSection.value = 'store'
  try {
    const response = await axiosInstance.get('/item-report-stores', {
      params: { stores: storeIds, item_id: selectedItem.value.item.id },  
      paramsSerializer: params => {
        return params.stores.map(id => `stores[]=${id}`).join('&') 
          + `&item_id=${params.item_id}`
      }
    })
    storeDetails.value = response.data.map((item, index)=>({
        ...item,
        SNo: index + 1,
        project : item.project.short_name,
        name : item.name,
        location: item?.location?.name ?? "--",
        quantity:formatNumber(item.item_quantity)
      }))
  } catch (error) {
    console.error(error)
  } finally {
    storeDetailsLoading.value = false
  }
}


const orderDetails = ref([]);
const orderColumns = ref(['SNo','order','project','purpose','requester','date','quantity']); 
const orderDetailsLoading = ref(false);
const getOrderDetails = async (storeIds) => {
  if (!storeIds || storeIds.length === 0) return
  orderDetailsLoading.value = true
  activeSection.value = 'order'
  try {
    const response = await axiosInstance.get('/item-report-orders', {
      params: { order_ids: storeIds, item_id: selectedItem.value.item.id },  
      paramsSerializer: params => {
        return params.order_ids.map(id => `order_ids[]=${id}`).join('&')
          + `&item_id=${params.item_id}`
      }
    })
    orderDetails.value = response.data.map((item, index)=>({
        ...item,
        SNo: index + 1,
        order:item.id,
        project:item.requisition?.project?.short_name ?? 'no project',
        purpose:item?.requisition?.approval_group?.name,
        requester:item?.requisition?.requester?.name,
        date:item.requisition.date,
        quantity:formatNumber(item.item_quantity)
      }))
  } catch (error) {
    console.error(error)
  } finally {
    orderDetailsLoading.value = false
  }
}

const grnDetails = ref([]);
const grnColumns = ref(['SNo','grn','lpo','project','receiver','requester','date','quantity']); 
const grnDetailsLoading = ref(false);
const getGrnDetails = async (storeIds) => {
  if (!storeIds || storeIds.length === 0) return
  grnDetailsLoading.value = true
  activeSection.value = 'grn'
  try {
    const response = await axiosInstance.get('/item-report-grns', {
