        ...item,
        SNo: index + 1,
        grn:item.id,
        lpo:item.approval_list_id,
        receiver:item.receiver.name,
        date:formatDate(item.updated_at),
        project:item?.approval?.requisition?.project?.short_name,
        requester:item.approval.requester.name,
        briefing:item?.approval?.requisition?.description,
        quantity:formatNumber(item.item_quantity)

      }))
  } catch (error) {
    console.error(error)
  } finally {
    grnDetailsLoading.value = false
  }
}



const ginDetails = ref([]);
const ginColumns = ref(['SNo','gin','requester','issuer','from','to','date','quantity']); 
const ginDetailsLoading = ref(false);
const getGinDetails = async (storeIds) => {
  if (!storeIds || storeIds.length === 0) return
  ginDetailsLoading.value = true
  activeSection.value = 'gin'
  try {
    const response = await axiosInstance.get('/item-report-gins', {
      params: { gin_ids: storeIds, item_id: selectedItem.value.item.id },  
      paramsSerializer: params => {
        return params.gin_ids.map(id => `gin_ids[]=${id}`).join('&')
          + `&item_id=${params.item_id}`
      }
    })
    ginDetails.value = response.data.map((item, index)=>({
        ...item,
        SNo: index + 1,
        gin:item.id,
        requester:item.requisition.requester.name,
        issuer:item.issuer.name,
        from : item.source_store?.project?.short_name + ' - '+ item?.source_store?.name ,
       to:['TRANSFER', 'CONVERSION'].includes(item.purpose)
  ? `${item?.destination_store?.project?.short_name || ''} - ${item?.destination_store?.name || 'DIRECT CONSUMPTION'}`.trim().replace(/^-\s*|\s*-\s*$/g, '')
  : 'DIRECT CONSUMPTION',
  date: formatDate(item.created_at),
   receiver : item?.good_delivery_note?.receiver.name ?? '---',
   quantity:formatNumber(item.item_quantity)
      }))
  } catch (error) {
    console.error(error)
  } finally {
    ginDetailsLoading.value = false
  }
}



const category = ref('')
const categories = ref([])

const getItemCategories = async () => {
  const res = await axiosInstance.get('/item-list-category')
  categories.value = res.data
}

watch(item, (newVal) => {
  if (newVal) getItems(`item_id=${newVal.id}`)
})

watch(item_id, (newVal) => {
  if (newVal) getItems(`item_id=${newVal}`)
})

watch(category, (newVal) => {
  if (newVal) getItems(`category_id=${newVal.id}`)
})





