const printGinDetails = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>GIN Details Report</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 13px; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  hr { border: 0; border-top: 0.5px solid #000; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>
<div class="company-title">
  <i>
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>
<hr style="margin-top:20px">
<div class="title"> (${selectedItem.value?.item?.name}) GOODS ISSUE NOTE DETAILS REPORT</div>
<hr>
<table>
  <thead>
    <tr>
      <th>No.</th>
      <th>GIN ID</th>
      <th>Requester</th>
      <th>Issuer</th>
      <th>From</th>
      <th>To</th>
      <th>Date</th>
      <th>Quantity</th>
    </tr>
  </thead>
  <tbody>
    ${ginDetails.value.map((row) => `
    <tr>
      <td>${row.SNo}</td>
      <td>${row.gin || 'N/A'}</td>
      <td>${row.requester || 'N/A'}</td>
      <td>${row.issuer || 'N/A'}</td>
      <td>${row.from || 'N/A'}</td>
      <td>${row.to || 'N/A'}</td>
      <td>${row.date || 'N/A'}</td>
      <td>${row.quantity || 'N/A'}</td>
    </tr>
    `).join('')}
  </tbody>
</table>
</body>
</html>`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();
    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => document.body.removeChild(iframe), 1000);
    };
  } catch (error) {
    console.error(`Failed to print: ${error.message}`);
  }
};

onMounted(() => {
  getItemsList()
  getItemCategories()
})
</script>